CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public.reservation_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),config jsonb NOT NULL DEFAULT '{"enabled":false,"approval_required":true,"games":[1,2,3,4,5],"estimates":[[15,20],[20,30],[25,35],[30,40],[35,50],[40,60]],"use_upper":true,"before_minutes":0,"after_minutes":0,"step_minutes":15,"advance_days":90,"lead_minutes":0,"weekly":[[[720,1200]],[[1050,1110]],[[630,780],[900,975]],[[630,780]],[[630,1110]],[[630,1320]],[[630,1320]]]}',updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.reservation_settings TO authenticated; GRANT ALL ON public.reservation_settings TO service_role;
ALTER TABLE public.reservation_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read reservation settings" ON public.reservation_settings FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
INSERT INTO public.reservation_settings(id) SELECT 1 FROM public.hours_of_operation LIMIT 1;
CREATE TABLE public.lane_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_key uuid NOT NULL UNIQUE,contact_name text NOT NULL,email text NOT NULL,phone text NOT NULL,starts_at timestamp NOT NULL,duration_minutes integer NOT NULL,before_minutes integer NOT NULL DEFAULT 0,after_minutes integer NOT NULL DEFAULT 0,games integer NOT NULL,allocations integer[] NOT NULL,lanes integer[] NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','declined','cancelled','completed')),notes text NOT NULL DEFAULT '',staff_notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),created_by uuid,updated_by uuid);
GRANT SELECT ON public.lane_reservations TO authenticated; GRANT ALL ON public.lane_reservations TO service_role;
ALTER TABLE public.lane_reservations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read reservations" ON public.lane_reservations FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
CREATE TABLE public.lane_occupancy(reservation_id uuid NOT NULL REFERENCES public.lane_reservations(id) ON DELETE CASCADE,lane integer NOT NULL CHECK(lane BETWEEN 1 AND 6),occupied tsrange NOT NULL,PRIMARY KEY(reservation_id,lane),EXCLUDE USING gist(lane WITH =,occupied WITH &&));
GRANT SELECT ON public.lane_occupancy TO authenticated; GRANT ALL ON public.lane_occupancy TO service_role;
ALTER TABLE public.lane_occupancy ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read lane occupancy" ON public.lane_occupancy FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
CREATE TABLE public.lane_schedule_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,lanes integer[] NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,weekday integer,start_minute integer NOT NULL DEFAULT 0,end_minute integer NOT NULL DEFAULT 1440,exceptions date[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.lane_schedule_blocks TO authenticated; GRANT ALL ON public.lane_schedule_blocks TO service_role;
ALTER TABLE public.lane_schedule_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read schedule blocks" ON public.lane_schedule_blocks FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
CREATE TABLE public.reservation_date_hours(day date PRIMARY KEY,windows jsonb NOT NULL DEFAULT '[]',note text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.reservation_date_hours TO authenticated; GRANT ALL ON public.reservation_date_hours TO service_role;
ALTER TABLE public.reservation_date_hours ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read date hours" ON public.reservation_date_hours FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
CREATE TABLE public.reservation_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reservation_id uuid REFERENCES public.lane_reservations(id) ON DELETE CASCADE,action text NOT NULL,actor_id uuid,occurred_at timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.reservation_audit TO authenticated; GRANT ALL ON public.reservation_audit TO service_role;
ALTER TABLE public.reservation_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read reservation audit" ON public.reservation_audit FOR SELECT TO authenticated USING(private.is_staff(auth.uid()));
ALTER TABLE public.seasonal_hour_schedules ADD COLUMN IF NOT EXISTS starts_on date;
ALTER TABLE public.seasonal_hour_schedules ADD COLUMN IF NOT EXISTS ends_on date;
UPDATE public.seasonal_hour_schedules SET starts_on='2025-07-01',ends_on='2025-08-31' WHERE starts_on IS NULL AND date_label='July 1 – August 31, 2025';
CREATE FUNCTION public.reservation_windows(p_day date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT windows FROM reservation_date_hours WHERE day=p_day),(SELECT config->'weekly'->extract(dow FROM p_day)::integer FROM reservation_settings WHERE id=1),'[]'::jsonb) $$;
REVOKE ALL ON FUNCTION public.reservation_windows(date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.reservation_duration(p_alloc integer[],p_games integer) RETURNS integer LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;n integer;highest integer:=0;v integer; BEGIN SELECT config INTO c FROM reservation_settings WHERE id=1; IF cardinality(p_alloc) NOT BETWEEN 1 AND 6 OR p_alloc IS NULL OR p_games IS NULL OR NOT(c->'games' @> to_jsonb(ARRAY[p_games])) THEN RAISE EXCEPTION 'Choose 1–6 lanes and an available number of games.'; END IF; FOREACH n IN ARRAY p_alloc LOOP IF n IS NULL OR n NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Each lane must have 1–6 bowlers.'; END IF; v:=(c->'estimates'->(n-1)->>(CASE WHEN (c->>'use_upper')::boolean THEN 1 ELSE 0 END))::integer*p_games;highest:=greatest(highest,v); END LOOP;RETURN highest;END $$;
REVOKE ALL ON FUNCTION public.reservation_duration(integer[],integer) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.reservation_free_lanes(p_start timestamp,p_duration integer,p_before integer,p_after integer,p_ignore uuid DEFAULT NULL) RETURNS integer[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(l ORDER BY l),'{}'::integer[]) FROM generate_series(1,6) l WHERE NOT EXISTS(SELECT 1 FROM lane_occupancy o WHERE o.lane=l AND(p_ignore IS NULL OR o.reservation_id<>p_ignore) AND o.occupied && tsrange(p_start-make_interval(mins=>p_before),p_start+make_interval(mins=>p_duration+p_after),'[)')) AND NOT EXISTS(SELECT 1 FROM lane_schedule_blocks b WHERE l=ANY(b.lanes) AND EXISTS(SELECT 1 FROM generate_series((p_start-make_interval(mins=>p_before))::date::timestamp,(p_start+make_interval(mins=>p_duration+p_after))::date::timestamp,'1 day') d WHERE d::date BETWEEN b.starts_on AND b.ends_on AND(b.weekday IS NULL OR extract(dow FROM d)=b.weekday) AND NOT(d::date=ANY(b.exceptions)) AND tsrange(d+make_interval(mins=>b.start_minute),d+make_interval(mins=>b.end_minute),'[)') && tsrange(p_start-make_interval(mins=>p_before),p_start+make_interval(mins=>p_duration+p_after),'[)'))) $$;
REVOKE ALL ON FUNCTION public.reservation_free_lanes(timestamp,integer,integer,integer,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.reservation_public_config() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT config||jsonb_build_object('today',(now() AT TIME ZONE 'America/Edmonton')::date,'timezone','America/Edmonton') FROM reservation_settings WHERE id=1 $$;
REVOKE ALL ON FUNCTION public.reservation_public_config() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reservation_public_config() TO anon,authenticated;
CREATE FUNCTION public.reservation_available(p_day date,p_alloc integer[],p_games integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;duration integer;w jsonb;minute integer;t timestamp;free integer[];result jsonb:='[]';staff boolean:=coalesce(private.is_staff(auth.uid()),false); BEGIN SELECT config INTO c FROM reservation_settings WHERE id=1;duration:=reservation_duration(p_alloc,p_games); IF NOT(c->>'enabled')::boolean AND NOT staff THEN RETURN jsonb_build_object('slots','[]'::jsonb,'duration',duration,'disabled',true); END IF; IF p_day IS NULL OR p_day<(now() AT TIME ZONE 'America/Edmonton')::date OR p_day>(now() AT TIME ZONE 'America/Edmonton')::date+(c->>'advance_days')::integer THEN RETURN jsonb_build_object('slots','[]'::jsonb,'duration',duration); END IF; FOR w IN SELECT value FROM jsonb_array_elements(reservation_windows(p_day)) LOOP minute:=(w->>0)::integer+(c->>'before_minutes')::integer; WHILE minute+duration+(c->>'after_minutes')::integer<=(w->>1)::integer LOOP t:=p_day::timestamp+make_interval(mins=>minute); IF t>=(now() AT TIME ZONE 'America/Edmonton')+make_interval(mins=>(c->>'lead_minutes')::integer) THEN free:=reservation_free_lanes(t,duration,(c->>'before_minutes')::integer,(c->>'after_minutes')::integer); IF cardinality(free)>=cardinality(p_alloc) THEN result:=result||jsonb_build_array(jsonb_build_object('time',to_char(t,'HH24:MI'),'available',cardinality(free))); END IF; END IF;minute:=minute+(c->>'step_minutes')::integer;END LOOP;END LOOP;RETURN jsonb_build_object('slots',result,'duration',duration,'disabled',false);END $$;
REVOKE ALL ON FUNCTION public.reservation_available(date,integer[],integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reservation_available(date,integer[],integer) TO anon,authenticated;
CREATE FUNCTION public.reservation_save(p jsonb,p_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;r lane_reservations;old lane_reservations;alloc integer[];selected integer[];free integer[];duration integer;t timestamp;st text;staff boolean:=coalesce(private.is_staff(auth.uid()),false);key uuid;n integer;windows jsonb; BEGIN PERFORM pg_advisory_xact_lock(6281962);IF p_id IS NOT NULL AND NOT staff THEN RAISE EXCEPTION 'Staff access required.';END IF;SELECT config INTO c FROM reservation_settings WHERE id=1;IF NOT staff AND NOT(c->>'enabled')::boolean THEN RAISE EXCEPTION 'Online reservations are not enabled. Please call the centre.';END IF;IF p_id IS NOT NULL THEN SELECT * INTO old FROM lane_reservations WHERE id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Reservation not found.';END IF;END IF;key:=coalesce((p->>'request_key')::uuid,old.request_key);IF key IS NULL THEN RAISE EXCEPTION 'Request identifier required.';END IF;IF p_id IS NULL AND EXISTS(SELECT 1 FROM lane_reservations WHERE request_key=key) THEN RETURN jsonb_build_object('received',true,'duplicate',true);END IF;alloc:=ARRAY(SELECT jsonb_array_elements_text(p->'allocations')::integer);duration:=reservation_duration(alloc,(p->>'games')::integer);IF staff AND p?'duration_minutes' THEN duration:=(p->>'duration_minutes')::integer;END IF;IF duration IS NULL OR duration NOT BETWEEN 1 AND 1440 THEN RAISE EXCEPTION 'Duration must be between 1 and 1440 minutes.';END IF;t:=(p->>'day')::date+(p->>'time')::time;IF t IS NULL THEN RAISE EXCEPTION 'Choose a date and start time.';END IF;st:=CASE WHEN staff THEN coalesce(p->>'status','pending') WHEN(c->>'approval_required')::boolean THEN 'pending' ELSE 'confirmed' END;IF st NOT IN('pending','confirmed','declined','cancelled','completed') THEN RAISE EXCEPTION 'Invalid reservation status.';END IF;IF length(trim(coalesce(p->>'contact_name',''))) NOT BETWEEN 2 AND 120 OR length(coalesce(p->>'email',''))>254 OR coalesce(p->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(trim(coalesce(p->>'phone',''))) NOT BETWEEN 7 AND 40 OR length(coalesce(p->>'notes',''))>3000 OR length(coalesce(p->>'staff_notes',''))>5000 THEN RAISE EXCEPTION 'Enter a valid name, email and phone; keep notes within the allowed length.';END IF;IF st IN('pending','confirmed') THEN IF NOT staff AND(t<(now() AT TIME ZONE 'America/Edmonton')+make_interval(mins=>(c->>'lead_minutes')::integer) OR t::date>(now() AT TIME ZONE 'America/Edmonton')::date+(c->>'advance_days')::integer) THEN RAISE EXCEPTION 'Choose a time within the booking window.';END IF;windows:=reservation_windows(t::date);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(windows) w WHERE t-make_interval(mins=>(c->>'before_minutes')::integer)>=t::date::timestamp+make_interval(mins=>(w->>0)::integer) AND t+make_interval(mins=>duration+(c->>'after_minutes')::integer)<=t::date::timestamp+make_interval(mins=>(w->>1)::integer)) THEN RAISE EXCEPTION 'This reservation does not fit the bookable hours.';END IF;free:=reservation_free_lanes(t,duration,(c->>'before_minutes')::integer,(c->>'after_minutes')::integer,p_id);IF cardinality(free)<cardinality(alloc) THEN RAISE EXCEPTION 'Those lanes are no longer available for the whole visit. Choose another time.';END IF;IF staff AND p?'lanes' THEN selected:=ARRAY(SELECT jsonb_array_elements_text(p->'lanes')::integer);IF cardinality(selected)<>cardinality(alloc) OR cardinality(selected)<>(SELECT count(DISTINCT x) FROM unnest(selected) x) OR NOT selected<@free THEN RAISE EXCEPTION 'Assigned lanes conflict with another reservation or block.';END IF;ELSE selected:=free[1:cardinality(alloc)];END IF;ELSE selected:=coalesce(old.lanes,ARRAY(SELECT generate_series(1,cardinality(alloc))));END IF;IF p_id IS NULL THEN INSERT INTO lane_reservations(request_key,contact_name,email,phone,starts_at,duration_minutes,before_minutes,after_minutes,games,allocations,lanes,status,notes,staff_notes,created_by,updated_by) VALUES(key,trim(p->>'contact_name'),trim(p->>'email'),trim(p->>'phone'),t,duration,(c->>'before_minutes')::integer,(c->>'after_minutes')::integer,(p->>'games')::integer,alloc,selected,st,coalesce(p->>'notes',''),CASE WHEN staff THEN coalesce(p->>'staff_notes','') ELSE '' END,auth.uid(),auth.uid()) RETURNING * INTO r;ELSE UPDATE lane_reservations SET contact_name=trim(p->>'contact_name'),email=trim(p->>'email'),phone=trim(p->>'phone'),starts_at=t,duration_minutes=duration,before_minutes=(c->>'before_minutes')::integer,after_minutes=(c->>'after_minutes')::integer,games=(p->>'games')::integer,allocations=alloc,lanes=selected,status=st,notes=coalesce(p->>'notes',''),staff_notes=coalesce(p->>'staff_notes',''),updated_at=now(),updated_by=auth.uid() WHERE id=p_id RETURNING * INTO r;END IF;DELETE FROM lane_occupancy WHERE reservation_id=r.id;IF st IN('pending','confirmed') THEN FOREACH n IN ARRAY selected LOOP INSERT INTO lane_occupancy VALUES(r.id,n,tsrange(t-make_interval(mins=>r.before_minutes),t+make_interval(mins=>duration+r.after_minutes),'[)'));END LOOP;END IF;INSERT INTO reservation_audit(reservation_id,action,actor_id,details) VALUES(r.id,CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END,auth.uid(),jsonb_build_object('before',CASE WHEN p_id IS NULL THEN NULL ELSE to_jsonb(old) END,'after',to_jsonb(r)));RETURN jsonb_build_object('received',true,'id',r.id,'status',st,'lanes',selected,'duration',duration);END $$;
REVOKE ALL ON FUNCTION public.reservation_save(jsonb,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reservation_save(jsonb,uuid) TO anon,authenticated;
CREATE FUNCTION public.reservation_staff(p_action text,p jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb;b lane_schedule_blocks;w jsonb;ranges jsonb;v_day date; BEGIN IF NOT coalesce(private.is_staff(auth.uid()),false) THEN RAISE EXCEPTION 'Staff access required.';END IF;PERFORM pg_advisory_xact_lock(6281962);IF p_action='read' THEN RETURN jsonb_build_object('settings',(SELECT config FROM reservation_settings WHERE id=1),'reservations',coalesce((SELECT jsonb_agg(r ORDER BY starts_at) FROM lane_reservations r),'[]'::jsonb),'blocks',coalesce((SELECT jsonb_agg(b) FROM lane_schedule_blocks b),'[]'::jsonb),'date_hours',coalesce((SELECT jsonb_agg(h ORDER BY day) FROM reservation_date_hours h),'[]'::jsonb),'audit',coalesce((SELECT jsonb_agg(a ORDER BY occurred_at DESC) FROM reservation_audit a),'[]'::jsonb));ELSIF p_action='settings' THEN c:=p;IF jsonb_typeof(c->'games')<>'array' OR jsonb_array_length(c->'games') NOT BETWEEN 1 AND 20 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(c->'games') x WHERE x::integer NOT BETWEEN 1 AND 20) OR jsonb_array_length(c->'estimates')<>6 OR jsonb_array_length(c->'weekly')<>7 THEN RAISE EXCEPTION 'Choose valid games, six estimates and seven days.';END IF;FOR w IN SELECT value FROM jsonb_array_elements(c->'estimates') LOOP IF jsonb_array_length(w)<>2 OR(w->>0)::integer NOT BETWEEN 1 AND 240 OR(w->>1)::integer NOT BETWEEN(w->>0)::integer AND 240 THEN RAISE EXCEPTION 'Estimates must have a valid minimum and maximum.';END IF;END LOOP;IF(c->>'before_minutes')::integer NOT BETWEEN 0 AND 120 OR(c->>'after_minutes')::integer NOT BETWEEN 0 AND 120 OR(c->>'step_minutes')::integer NOT BETWEEN 5 AND 120 OR(c->>'advance_days')::integer NOT BETWEEN 1 AND 730 OR(c->>'lead_minutes')::integer NOT BETWEEN 0 AND 10080 THEN RAISE EXCEPTION 'Booking rules are outside the allowed range.';END IF;PERFORM(c->>'enabled')::boolean,(c->>'approval_required')::boolean,(c->>'use_upper')::boolean;FOR ranges IN SELECT value FROM jsonb_array_elements(c->'weekly') LOOP FOR w IN SELECT value FROM jsonb_array_elements(ranges) LOOP IF jsonb_array_length(w)<>2 OR(w->>0)::integer NOT BETWEEN 0 AND 1439 OR(w->>1)::integer NOT BETWEEN(w->>0)::integer+1 AND 1440 THEN RAISE EXCEPTION 'Bookable windows must run forward within one day.';END IF;END LOOP;END LOOP;IF EXISTS(SELECT 1 FROM lane_reservations r WHERE status IN('pending','confirmed') AND starts_at::date>=(now() AT TIME ZONE 'America/Edmonton')::date AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce((SELECT windows FROM reservation_date_hours WHERE day=r.starts_at::date),c->'weekly'->extract(dow FROM r.starts_at)::integer)) x WHERE r.starts_at-make_interval(mins=>r.before_minutes)>=r.starts_at::date::timestamp+make_interval(mins=>(x->>0)::integer) AND r.starts_at+make_interval(mins=>r.duration_minutes+r.after_minutes)<=r.starts_at::date::timestamp+make_interval(mins=>(x->>1)::integer))) THEN RAISE EXCEPTION 'These hours would exclude an active reservation. Resolve that reservation first.';END IF;UPDATE reservation_settings SET config=c,updated_at=now(),updated_by=auth.uid() WHERE id=1;ELSIF p_action='block' THEN b.id:=coalesce((p->>'id')::uuid,gen_random_uuid());b.title:=trim(p->>'title');b.lanes:=ARRAY(SELECT jsonb_array_elements_text(p->'lanes')::integer);b.starts_on:=(p->>'starts_on')::date;b.ends_on:=(p->>'ends_on')::date;b.weekday:=(p->>'weekday')::integer;b.start_minute:=(p->>'start_minute')::integer;b.end_minute:=(p->>'end_minute')::integer;b.exceptions:=ARRAY(SELECT jsonb_array_elements_text(coalesce(p->'exceptions','[]'))::date);IF b.title IS NULL OR length(b.title) NOT BETWEEN 1 AND 150 OR cardinality(b.lanes) NOT BETWEEN 1 AND 6 OR NOT b.lanes<@ARRAY[1,2,3,4,5,6] OR b.starts_on IS NULL OR b.ends_on IS NULL OR b.ends_on<b.starts_on OR b.ends_on>b.starts_on+730 OR b.start_minute IS NULL OR b.end_minute IS NULL OR b.start_minute NOT BETWEEN 0 AND 1439 OR b.end_minute NOT BETWEEN b.start_minute+1 AND 1440 OR(b.weekday IS NOT NULL AND b.weekday NOT BETWEEN 0 AND 6) THEN RAISE EXCEPTION 'Enter valid block dates, lanes and times.';END IF;IF EXISTS(SELECT 1 FROM lane_occupancy o,generate_series(b.starts_on::timestamp,b.ends_on::timestamp,'1 day') d WHERE o.lane=ANY(b.lanes) AND(b.weekday IS NULL OR extract(dow FROM d)=b.weekday) AND NOT(d::date=ANY(b.exceptions)) AND o.occupied && tsrange(d+make_interval(mins=>b.start_minute),d+make_interval(mins=>b.end_minute),'[)')) THEN RAISE EXCEPTION 'This block conflicts with an active reservation. No reservation was changed.';END IF;INSERT INTO lane_schedule_blocks(id,title,lanes,starts_on,ends_on,weekday,start_minute,end_minute,exceptions,updated_by) VALUES(b.id,b.title,b.lanes,b.starts_on,b.ends_on,b.weekday,b.start_minute,b.end_minute,b.exceptions,auth.uid()) ON CONFLICT(id) DO UPDATE SET title=excluded.title,lanes=excluded.lanes,starts_on=excluded.starts_on,ends_on=excluded.ends_on,weekday=excluded.weekday,start_minute=excluded.start_minute,end_minute=excluded.end_minute,exceptions=excluded.exceptions,updated_at=now(),updated_by=auth.uid();ELSIF p_action='remove_block' THEN DELETE FROM lane_schedule_blocks WHERE id=(p->>'id')::uuid;ELSIF p_action='date_hours' THEN v_day:=(p->>'day')::date;ranges:=p->'windows';IF v_day IS NULL OR jsonb_typeof(ranges)<>'array' THEN RAISE EXCEPTION 'Choose a date and hours.';END IF;FOR w IN SELECT value FROM jsonb_array_elements(ranges) LOOP IF jsonb_array_length(w)<>2 OR(w->>0)::integer NOT BETWEEN 0 AND 1439 OR(w->>1)::integer NOT BETWEEN(w->>0)::integer+1 AND 1440 THEN RAISE EXCEPTION 'Enter valid hours.';END IF;END LOOP;IF EXISTS(SELECT 1 FROM lane_reservations r WHERE status IN('pending','confirmed') AND starts_at::date=v_day AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(ranges) x WHERE r.starts_at-make_interval(mins=>r.before_minutes)>=v_day::timestamp+make_interval(mins=>(x->>0)::integer) AND r.starts_at+make_interval(mins=>r.duration_minutes+r.after_minutes)<=v_day::timestamp+make_interval(mins=>(x->>1)::integer))) THEN RAISE EXCEPTION 'These hours conflict with an active reservation.';END IF;INSERT INTO reservation_date_hours(day,windows,note,updated_by) VALUES(v_day,ranges,left(coalesce(p->>'note',''),500),auth.uid()) ON CONFLICT(day) DO UPDATE SET windows=excluded.windows,note=excluded.note,updated_at=now(),updated_by=auth.uid();ELSIF p_action='remove_date_hours' THEN v_day:=(p->>'day')::date;IF EXISTS(SELECT 1 FROM lane_reservations r WHERE status IN('pending','confirmed') AND starts_at::date=v_day AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements((SELECT config->'weekly'->extract(dow FROM v_day)::integer FROM reservation_settings WHERE id=1)) x WHERE r.starts_at-make_interval(mins=>r.before_minutes)>=v_day::timestamp+make_interval(mins=>(x->>0)::integer) AND r.starts_at+make_interval(mins=>r.duration_minutes+r.after_minutes)<=v_day::timestamp+make_interval(mins=>(x->>1)::integer))) THEN RAISE EXCEPTION 'Restoring regular hours conflicts with a reservation.';END IF;DELETE FROM reservation_date_hours WHERE day=v_day;ELSE RAISE EXCEPTION 'Unknown action.';END IF;INSERT INTO reservation_audit(action,actor_id,details) VALUES(p_action,auth.uid(),p);RETURN jsonb_build_object('saved',true);END $$;
REVOKE ALL ON FUNCTION public.reservation_staff(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reservation_staff(text,jsonb) TO authenticated;
CREATE FUNCTION public.submit_event_inquiry(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(trim(coalesce(p->>'contact_name',''))) NOT BETWEEN 2 AND 120 OR coalesce(p->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(p->>'email')>254 OR length(trim(coalesce(p->>'phone',''))) NOT BETWEEN 7 AND 40 OR coalesce((p->>'party_size')::integer,0) NOT BETWEEN 1 AND 1000 OR length(coalesce(p->>'notes',''))>3000 OR coalesce(p->>'booking_type','') NOT IN('Birthday party','Fundraiser','Large group','Whole-building rental','Meeting-room rental','Other special event') OR(p->>'requested_date') IS NULL OR(p->>'requested_date')::date<(now() AT TIME ZONE 'America/Edmonton')::date THEN RAISE EXCEPTION 'Enter valid contact details, event type, future date and attendance.';END IF;INSERT INTO booking_requests(booking_type,contact_name,email,phone,requested_date,requested_time,party_size,lanes,notes,status,created_by) VALUES(p->>'booking_type',trim(p->>'contact_name'),trim(p->>'email'),trim(p->>'phone'),(p->>'requested_date')::date,coalesce(nullif(p->>'requested_time','')::time,'00:00'),(p->>'party_size')::integer,1,coalesce(p->>'notes',''),'new',auth.uid());RETURN jsonb_build_object('received',true);END $$;
REVOKE ALL ON FUNCTION public.submit_event_inquiry(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_event_inquiry(jsonb) TO anon,authenticated;
REVOKE INSERT ON public.booking_requests FROM anon,authenticated;